draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // body
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*20, H/2 + 50, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*20, H/2 - 30, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*20, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t)*20 - 20 + Math.sin(t*2)*10, H/2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*20, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t)*20 + 20 + Math.sin(t*2)*10, H/2 + 120);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*20, H/2 - 10);
  ctx.lineTo(W/2 + Math.sin(t)*20 - 30 + Math.cos(t*2)*10, H/2 + 20);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*20, H/2 - 10);
  ctx.lineTo(W/2 + Math.sin(t)*20 + 30 + Math.cos(t*2)*10, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
